public interface Renderable {
    void render();
}

public class CoreComponent implements Renderable {
    @Override
    public void render() {
        System.out.println("Rendering base component");
    }
}

public abstract class ComponentDecorator implements Renderable {
    protected final Renderable wrappee;

    protected ComponentDecorator(Renderable wrappee) {
        this.wrappee = wrappee;
    }

    @Override
    public void render() {
        wrappee.render();
    }
}

public class LoggingDecorator extends ComponentDecorator {
    public LoggingDecorator(Renderable wrappee) {
        super(wrappee);
    }

    @Override
    public void render() {
        System.out.println("[DEBUG] Entering render()");
        super.render();
        System.out.println("[DEBUG] Exiting render()");
    }
}
